// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');

// Module-level font loading
const { fontFamily: bebasFamily } = loadBebas();



export type VerticalSwapProps = Record<string, any>;

const VerticalSwap: React.FC<VerticalSwapProps> = ({
  backgroundColor = "#0D0D0D",
  transparentBackground = false,
  durationInSeconds = 4,
  topName = "Your name",
  bottomName = "Their name",
  topNameColor = "#F5A623",
  bottomNameColor = "#888888",
  messageText = "This is happening right now.",
  messageColor = "#FFFFFF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Scene 1: Swap Animation (0.0s - 1.5s)
  const swapDurationFrames = fps * 1.5;
  
  const swapProgress = interpolate(frame, [0, swapDurationFrames], [0, 1], {
    easing: Easing.inOut(Easing.ease),
    extrapolateRight: "clamp",
  });

  const initialTopY = height * 0.35;
  const initialBottomY = height * 0.65;

  const currentTopY = interpolate(
    swapProgress,
    [0, 1],
    [initialTopY, initialBottomY]
  );
  const currentBottomY = interpolate(
    swapProgress,
    [0, 1],
    [initialBottomY, initialTopY]
  );

  // Color Swapping Logic
  const currentTopColor = interpolateColors(
    swapProgress,
    [0, 1],
    [topNameColor, bottomNameColor]
  );
  
  const currentBottomColor = interpolateColors(
    swapProgress,
    [0, 1],
    [bottomNameColor, topNameColor]
  );

  // Scene 2: Message Appearance (1.5s - 2.5s)
  const messageStartFrame = fps * 1.5;
  const messageEndFrame = fps * 2.5;

  const messageOpacity = interpolate(
    frame,
    [messageStartFrame, messageEndFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const messageYOffset = interpolate(
    frame,
    [messageStartFrame, messageEndFrame],
    [50, 0],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Responsive Layout Scaling
  const s = Math.min(width, height);
  const nameFontSize = s * 0.12;
  const messageFontSize = s * 0.07;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: bebasFamily,
        overflow: "hidden",
      }}
    >
      {/* Top Name (Animates down) */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          top: currentTopY,
          transform: "translateY(-50%)",
          textAlign: "center",
          fontSize: nameFontSize,
          color: currentTopColor,
          margin: 0,
          padding: `0 ${width * 0.05}px`,
          lineHeight: 1,
          transition: "none",
        }}
      >
        {topName}
      </div>

      {/* Bottom Name (Animates up) */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          top: currentBottomY,
          transform: "translateY(-50%)",
          textAlign: "center",
          fontSize: nameFontSize,
          color: currentBottomColor,
          margin: 0,
          padding: `0 ${width * 0.05}px`,
          lineHeight: 1,
          transition: "none",
        }}
      >
        {bottomName}
      </div>

      {/* Scene 2 Message Text */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          top: height * 0.82,
          transform: `translateY(calc(-50% + ${messageYOffset}px))`,
          textAlign: "center",
          fontSize: messageFontSize,
          color: messageColor,
          opacity: messageOpacity,
          margin: 0,
          padding: `0 ${width * 0.05}px`,
          lineHeight: 1.1,
          transition: "none",
        }}
      >
        {messageText}
      </div>
    </AbsoluteFill>
  );
};

export default VerticalSwap;